{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Felbamate, a small lipophilic phenyl-containing drug, has >90% absolute oral bioavailability in humans, supporting high F for the query despite low Morgan similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Terodiline, a lipophilic diphenylpropylamine, has a mean absolute oral bioavailability of 92% in healthy volunteers, showing that lipophilic drugs with an ionizable amine can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Phenylbutyrate, an aromatic ester, shows 78% oral bioavailability in patients, supporting high F for a lipophilic aromatic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tapentadol, despite extensive first-pass metabolism, has an absolute oral bioavailability of approximately 32%, which is above the 20% threshold and therefore supports the high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Baicalein, a polyhydroxylated flavonoid, has low oral bioavailability in humans, but its poor solubility and extensive conjugation are not representative of the lipophilic 4-hydroxycoumarin query; this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic 4-hydroxycoumarin (phenprocoumon-like) with an enolic hydroxyl and phenylpropyl side chain, expected to be well absorbed. Multiple human oral bioavailability values from structurally distant but lipophilic drugs (felbamate >90%, terodiline 92%, phenylbutyrate 78%, tapentadol 32%) all exceed the 20% threshold. The only low-F analogue, baicalein, is a polyhydroxylated flavonoid with poor solubility and extensive conjugation, so its low F does not transfer. Therefore predict high F (>=20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule in the supplied evidence.",
    "All retrieved analogues have low Morgan similarity (<0.29), limiting structural transfer.",
    "The only low-F analogue (baicalein) has a different absorption and metabolism profile and is not representative of the query.",
    "Some supporting records are not explicitly absolute bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

